def countPairsAtDistance(n, edges, k):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    parent = [-1] * n
    order = [0]
    seen = [False] * n
    seen[0] = True
    for u in order:
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                parent[v] = u
                order.append(v)
    cnt = [None] * n
    total = 0
    for v in reversed(order):
        cur = [0] * (k + 1)
        cur[0] = 1
        for c in adj[v]:
            if c == parent[v]:
                continue
            ch = cnt[c]
            cnt[c] = None
            for i in range(k):
                total += cur[i] * ch[k - 1 - i]
            for j in range(k):
                cur[j + 1] += ch[j]
        cnt[v] = cur
    return total
